import { useState, useEffect, useCallback } from 'react'
import { StyleContainer } from './index.style.js'

function NumberStepper({
  min = 0,
  max,
  decimal_place = 0,
  increment_by = 1,
  defaultValue,
  disabled,
  onChange,
  className,
  style,
}) {
  const toCorrectDecimalPlace = useCallback(
    (num) => Number(num?.toFixed(decimal_place)),
    [decimal_place]
  )

  const initialValue = Number(defaultValue ?? 0)
  const [value, setValue] = useState(toCorrectDecimalPlace(initialValue))

  useEffect(() => {
    setValue(toCorrectDecimalPlace(Number(defaultValue ?? 0)))
  }, [defaultValue, toCorrectDecimalPlace])

  const handleDecrement = () => {
    const next = Math.max(toCorrectDecimalPlace(value - increment_by), min)
    setValue(next)
    onChange?.(next)
  }

  const handleIncrement = () => {
    const next =
      max !== undefined
        ? Math.min(toCorrectDecimalPlace(value + increment_by), max)
        : toCorrectDecimalPlace(value + increment_by)
    setValue(next)
    onChange?.(next)
  }

  const handleInputChange = (e) => {
    const _value = toCorrectDecimalPlace(Number(e.target.value))
    setValue(_value)
    onChange?.(_value)
  }

  const handleInputBlur = () => {
    const clamped = max !== undefined ? Math.min(Math.max(value, min), max) : Math.max(value, min)
    setValue(clamped)
    onChange?.(clamped)
  }

  return (
    <StyleContainer className={className} style={style} data-testid="number-stepper">
      <button
        className="stepper-btn btn-decrement"
        onClick={handleDecrement}
        disabled={min !== undefined && value <= min}
        data-testid="stepper-decrement"
        aria-label="Decrease value"
      >
        <span>-</span>
      </button>
      <input
        type="number"
        className="stepper-input"
        disabled={disabled}
        value={value.toFixed(decimal_place)}
        onChange={handleInputChange}
        onBlur={handleInputBlur}
        data-testid="stepper-input"
        aria-label="Stepper input"
      />
      <button
        className="stepper-btn btn-increment"
        onClick={handleIncrement}
        disabled={max !== undefined && value >= max}
        data-testid="stepper-increment"
        aria-label="Increase value"
      >
        <span>+</span>
      </button>
    </StyleContainer>
  )
}

export default NumberStepper
