import { Component } from 'react'
import PropTypes from 'prop-types'
import NumberFormat from 'react-number-format'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import CustomCheckbox from '../../../../../components/CustomCheckbox'
import { formatMoney } from '../../../../../helpers/utility'

class AddonItemWithouLimit extends Component {
  static propTypes = {
    isChecked: PropTypes.bool,
    name: PropTypes.string,
    title: PropTypes.string,
    premium: PropTypes.number,
    onChangeCheckBox: PropTypes.func
  }

  render () {
    const {
      className, name, isChecked, onChangeCheckBox,
      title, premium
    } = this.props
    return (
      <Row justify='space-between' className={className}>
        <div>
          <CustomText size='12px' color={AgentColorPallette.fontDarkerGrey} weight={800}>
            {title}
          </CustomText>
          <CustomText size='12px' color={AgentColorPallette.fontSemiGrey} top='2px'>
            <NumberFormat
              thousandSeparator='.'
              decimalSeparator=','
              className='format-input'
              prefix='Mulai dari  Rp '
              value={formatMoney(premium, 0)}
              displayType='text'
            />
          </CustomText>
        </div>
        <CustomCheckbox
          isChecked={isChecked}
          onChange={onChangeCheckBox}
          name={name}
          id={name}
        />
      </Row>
    )
  }
}

export default AddonItemWithouLimit
