import { Component } from 'react'
import PropTypes from 'prop-types'
import { PackageItemStyle } from './index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { CustomText } from '../../../../../components'
import { formatMoney } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import Collapsible from '../../../../../components/Collapsible'
import AddonOnPackageList from '../AddonOnPackageList'
import { setToLocalStorage } from '../../../../../helpers/localstorage'
import { PACKAGE_CODE, POLICY_PKG_DATA } from '../../../../../constants/cookies'
import { DisplayFlexRCC, Row } from '../../../../../commonStyle/index.style'
import { TIER_A, TIER_B } from '../../../../../images/imageUrl'

class PackageItem extends Component {
  static propTypes = {
    packageItem: PropTypes.object,
    selectedAddon: PropTypes.object,
    applicationData: PropTypes.object,
    history: PropTypes.object,
    purchaseType: PropTypes.string
  }

  handleCardClick = (packageItem) => {
    // getPayload for addons and map data
    const { applicationData, purchaseType } = this.props
    const pkgData = {
      applicationData,
      purchaseType,
      package_code: packageItem.code,
      selectedAddon: this.getMatchSelectedAddon()
    }
    setToLocalStorage(PACKAGE_CODE, packageItem.code)
    setToLocalStorage(POLICY_PKG_DATA, pkgData)
    this.props.history.push({
      pathname: '/motor_vehicle/packages/details',
      state: pkgData
    })
  }

  getMatchSelectedAddon = () => {
    const { packageItem, selectedAddon } = this.props
    const { add_ons: categoryAddons = [] } = packageItem
    const mapAddonsData = {
      ...selectedAddon
    }
    categoryAddons && categoryAddons.forEach(element => {
      const { add_on: addons = [] } = element
      addons.forEach(addon => {
        if (addon.matched) {
          // match exits else remove code
          // do nothing now
          if (!mapAddonsData[addon.add_on_code]) {
            mapAddonsData[addon.add_on_code] = addon
          }
        } else {
          delete mapAddonsData[addon.add_on_code]
        }
      })
    })
    return mapAddonsData
  }

  getAddonsRender = (addonsData) => (
    <div className='addons-wrapper'>
      {
        addonsData.map(addon =>
          (
            <Collapsible
              header={addon.category_name}
              key={addon.category_code}
              titleClassName='addons-title'
            >
              {
                addon.add_on.map(addonItem => (
                  <AddonOnPackageList
                    title={addonItem.add_on_name}
                    isCheck={addonItem.matched}
                    key={addonItem.add_on_code}
                    addon={addonItem}
                    extraDetails={addonItem.extra_details}
                  />
                ))
              }
            </Collapsible>
          )
        )
      }
    </div>
  )

  render () {
    const { packageItem } = this.props
    const { add_ons: addonsData = [] } = packageItem
    return (
      <PackageItemStyle>
        <div className='pkg-details'>
          <Row
            id={`mobilPkgCardSelect-${packageItem.code}`}
            data-gtm-element-id='MV-packages-list'
            data-package-code={`MV-Card-Select-${packageItem.code}`}
            className='pkg-name-box'
            onClick={e => this.handleCardClick(packageItem)}
          >
            <DisplayFlexRCC
              className='package-img-box'
              data-gtm-element-id='MV-packages-list'
              data-package-code={`MV-${packageItem.code}`}
            >
              <img
                data-gtm-element-id='MV-packages-list'
                data-package-code={`MV-${packageItem.code}`}
                className='package-img'
                src={packageItem.provider.logo_url}
                alt='package-logo'
              />
            </DisplayFlexRCC>
            <div
              data-gtm-element-id='MV-packages-list'
              data-package-code={`MV-${packageItem.code}`}
            >
              <CustomText
                color={AgentColorPallette.fontSecondary}
                data-gtm-element-id='MV-packages-list'
                data-package-code={`MV-${packageItem.code}`}
              >
                {packageItem.provider.name}
              </CustomText>
              <CustomText
                color={AgentColorPallette.black}
                weight='800'
                size='14px'
                bottom='5px'
                data-gtm-element-id='MV-packages-list'
                data-package-code={`MV-${packageItem.code}`}
              >
                {packageItem.name}
              </CustomText>
              {
                ['A', 'B'].includes(packageItem.provider_category) && (
                  <img src={packageItem.provider_category === 'A' ? TIER_A : TIER_B} alt='Preferred' />
                )
              }
            </div>
          </Row>
          <CustomText className='package-price' color={AgentColorPallette.blue} weight='800' size='18px'>
            {formatMoney(packageItem.premium.amount, 0)} / {packageItem.premium.period === 12 ? `12 ${LANG_STRINGS.months}` : `${packageItem.premium.period} ${LANG_STRINGS.year}`}
          </CustomText>
          <CustomText color={AgentColorPallette.black} className='package-price'>
            {LANG_STRINGS.valueOfCoverage} : <b>{formatMoney(packageItem.sum_insured, 0)}</b>
          </CustomText>
          <CustomText
            color={AgentColorPallette.black}
            className='package-price'
            dangerouslySetInnerHTML={{
              __html: LANG_STRINGS.getPointsOnTransactions.replace('XXXX', Math.floor(packageItem.points))
            }}
          />
          {
            addonsData && !!addonsData.length && (this.getAddonsRender(addonsData))
          }
        </div>
        <div
          className='choose-button'
          onClick={() => this.handleCardClick(packageItem)}
          id={`mobilPkgSelect-${packageItem.code}`}
          data-gtm-element-id='MV-packages-list'
          data-package-code={`MV-Select-${packageItem.code}`}
        >
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            weight='800'
            size='12px'
            data-gtm-element-id='MV-packages-list'
            data-package-code={`MV-Select-${packageItem.code}`}
          >
            {LANG_STRINGS.buyPackage}
          </CustomText>
        </div>
      </PackageItemStyle>
    )
  }
}

export default PackageItem
