import { PureComponent } from 'react'
import PropTypes from 'prop-types'
import { Row, DisplayCircleIcon } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { INFO } from '../../../../../images'
import ToolTip from '../../../../../components/ToolTip'
import { LANG_STRINGS } from '../../../../../lang'

class AddonOnPackageList extends PureComponent {
  static propTypes = {
    addon: PropTypes.object,
    title: PropTypes.string,
    extraDetails: PropTypes.array,
    isCheck: PropTypes.bool
  }

  getDataViewForTip = () => {
    const { extraDetails } = this.props
    return (
      <ul className='extra-details-list'>
        {
          extraDetails.map((item, index) => <li key={`extra-details_${index}`}>{item}</li>)
        }
      </ul>
    )
  }

  render () {
    const { isCheck, extraDetails, addon = {} } = this.props
    const { green, errorDark, limeGreen } = AgentColorPallette
    return (
      <Row justify='space-between' align='center'>
        <Row align='center' className='addon-item'>
          <CustomText
            size='10px'
            color={AgentColorPallette.black}
          >
            {addon.add_on_name}
          </CustomText>
          &nbsp;&nbsp;
          {
            !!extraDetails.length && (
              <ToolTip dataView={this.getDataViewForTip()}>
                {
                  this.getDataViewForTip() && (
                    <DisplayCircleIcon width='18px' height='18px'>
                      <img src={INFO} alt='' />
                    </DisplayCircleIcon>
                  )
                }
              </ToolTip>
            )
          }
          {
            addon.auto_applied && (
              <ToolTip
                dataView={
                  <span className='addon_free_info'>
                    {
                      addon.premium ? LANG_STRINGS.itsNotFreeAddon : LANG_STRINGS.itsFreeAddonPartOfBenefit
                    }
                  </span>
                }
                className={addon.premium ? 'addon-paid' : 'addon-free'}
              >
                <DisplayCircleIcon
                  width='8px'
                  height='8px'
                  bgColor={addon.premium ? errorDark : limeGreen}
                />
              </ToolTip>
            )
          }
        </Row>
        <CustomText size='10px' color={isCheck ? green : errorDark} bottom='8px'>
          {isCheck ? <i className='fa fa-check' /> : <i className='fa fa-times' />}
        </CustomText>
      </Row>
    )
  }
}

export default AddonOnPackageList
