import { updateLoader, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useEffect, useMemo, useRef, useCallback, useState } from 'react'
import { Container, CustomText } from '../../../../../../components'
import StepsHeader from '../../../../../../components/StepsHeader'
import { getFromLocalStorageData, setToLocalStorage } from '../../../../../../helpers/localstorage'
import { getValueFromLocationState } from '../../../../../../helpers/utility'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../lang'
import { Row } from '../../../../../../commonStyle/index.style'
import { PACKAGE_ADDONS_KEY, POLICY_DATA_WITH_ADDONS, POLICY_PKG_REQ_DATA } from '../../../../../../constants/cookies'
import PackageNotFound from '../../../components/PackageNotFound'
import { useGetPackages } from '../../../state/hooks/usePackages'
import { PackageListStyle } from './index.style'
import { useHistory } from 'react-router-dom'
import AdditionAddonsHeader from '../../../../Application/components/AdditionAddonsHeader'
import isEmpty from 'lodash/isEmpty'
import AddonPackagesModal from '../../../../Application/components/AddonPackagesModal'
import { getAddonsMapBody, getPackagesReqBody } from '../../../../../../helpers/getPackageBody'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import PackageItem from '../../../../Application/components/PkgItemOld'
import { connect } from 'react-redux'
import policyActions from '../../../../../../redux/policy/action'
import { disableNativePullToRefresh, enableNativePullToRefresh } from '../../../../../../bridges/android'

const { saveAddonsToStore } = policyActions

function PackageListOldContainer (props) {
  const history = useHistory()
  const [addonsModal, setAddonsModal] = useState({
    showModal: false
  })

  const [{ getPackagesData = {} }, getPackagesRequest] = useGetPackages()
  const pageData = useMemo(() => {
    const applicationData = getFromLocalStorageData(POLICY_PKG_REQ_DATA)
    const map = {
      applicationData,
      productCode: applicationData.code || getValueFromLocationState.call(this, 'productCode'),
      purchaseType: applicationData.purchase_type || getValueFromLocationState.call(this, 'purchaseType')
    }
    // if product code not exist then redirect to dashboard
    if (!map.productCode) {
      return history.replace('/dashboard') || {}
    }
    return map
  }, [history])
  const isPkgsEmpty = useMemo(() => {
    if (getPackagesData['error-code']) {
      return true
    }
    return !getPackagesData?.complete_match?.length && !getPackagesData?.no_match?.length && !getPackagesData?.partial_match?.length
  }, [getPackagesData])
  const initialAddonsData = useRef(getFromLocalStorageData(PACKAGE_ADDONS_KEY))
  const [{ GET_PACKAGES_LOADER }, dispatchLoader] = useLoaderContextValue()

  const validateApplicationData = useCallback((applicationData = {}) => {
    const requiredProperty = [
      'package_type', 'vehicle_type', 'brand', 'model', 'variant',
      'variant_code', 'year', 'region_code', 'vehicle_sum_insured'
    ]
    // some function returns true if any one value is not valid\
    // so make its false if its return true
    const isValid = requiredProperty.some((item) => {
      return !applicationData[item]
    })

    return !isValid
  }, [])

  const getInitialPackages = useCallback((addonsPayload = {}) => {
    if (!validateApplicationData(pageData.applicationData)) {
      ShowSnackbar.error({
        visible: true,
        text: ERROR_LANG.pleaseSelectTheProductForInsurance
      })
      return history.replace('/dashboard')
    }
    let renewalExpiredData = {}
    if (pageData.applicationData.expired) {
      renewalExpiredData = {
        expired: true,
        org_policy_ref_id: pageData.applicationData.org_policy_ref_id
      }
    }
    const payload = {
      ...renewalExpiredData,
      ...getPackagesReqBody(pageData.applicationData, true),
      ...addonsPayload,
      purchase_type: pageData.purchaseType,
      code: pageData.productCode
    }
    delete payload.errorField
    if (!isEmpty(addonsPayload)) {
      setToLocalStorage(POLICY_DATA_WITH_ADDONS, payload)
    }

    if (pageData.applicationData.year_based_package_type_map) {
      payload.year_based_package_type_map = pageData.applicationData.year_based_package_type_map
    }

    getPackagesRequest({
      body: {
        ...payload
      }
    })
  }, [getPackagesRequest, pageData, validateApplicationData, history])

  useEffect(() => {
    if (GET_PACKAGES_LOADER === undefined) {
      if (!isEmpty(initialAddonsData.current)) {
        props.saveAddonsToStore(initialAddonsData.current)
        getInitialPackages(getAddonsMapBody(initialAddonsData.current))
      } else {
        getInitialPackages()
      }
    }
  }, [getInitialPackages, props, GET_PACKAGES_LOADER])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_PACKAGES_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const handleShowModal = useCallback(() => {
    disableNativePullToRefresh()
    setAddonsModal({
      showModal: true
    })
  }, [])

  const handleCloseModal = useCallback(() => {
    enableNativePullToRefresh()
    setAddonsModal({
      showModal: false
    })

    if (isEmpty(props.savedAddonsData)) {
      // if addons empty then also called packages
      // with initial data so that we can show packages with
      // motor vehicle
      getInitialPackages()
    } else {
      getInitialPackages(getAddonsMapBody(props.savedAddonsData))
    }
  }, [getInitialPackages, props])

  const handleToGetPkgs = useCallback((data) => {
    // set the selected Items to localstorage also so that
    // if user reload data can easily access
    props.saveAddonsToStore(data)
    setToLocalStorage(PACKAGE_ADDONS_KEY, data)
    getInitialPackages(getAddonsMapBody(data))
    setAddonsModal({
      showModal: false
    })
  }, [props, getInitialPackages])

  const getPackageContainer = useCallback((data = [], id) => {
    return data.length > 0 && data.map((packageItem, index) => (
      <PackageItem
        key={`${id}_${index}`}
        packageItem={packageItem}
        history={history}
        purchaseType={pageData.purchaseType}
        applicationData={pageData.applicationData}
        selectedAddon={props.savedAddonsData}
      />
    ))
  }, [pageData, props, history])

  const getTitle = useCallback((count, text) => {
    return (
      <Row className='package-title'>
        <CustomText color={AgentColorPallette.black} weight={800}>
          ({count})&nbsp;
        </CustomText>
        <CustomText color={AgentColorPallette.fontDarkerGrey} weight={800}>
          {text}
        </CustomText>
      </Row>
    )
  }, [])

  return (
    <Container
      title='Daftar Paket Asuransi'
      loader={GET_PACKAGES_LOADER}
      hideBottomTabs
      className={isPkgsEmpty ? 'bg-white' : ''}
      backBtnId='mobilPackagesStepBack_2'
    >
      <PackageListStyle isPkgNotExist={isPkgsEmpty}>
        <div className='steps-header-custom'>
          <StepsHeader className='application-steps-header' leftText='PILIH PAKET' current='2' totalSteps='8' />
        </div>
        {

        }
        {
          (GET_PACKAGES_LOADER === false) && !isPkgsEmpty && (
            <>
              <CustomText
                className='pkg-maximum-discount'
                size='13px'
                weight={800}
                textAlign='center'
              >
                {LANG_STRINGS.maximumBonusForMotorVehicle}
              </CustomText>
              <AdditionAddonsHeader id='mobilPackageSelectAddonStep_2' onClick={handleShowModal} />
              {
                !!(getPackagesData?.complete_match.length > 0) && (
                  <>
                    {getTitle(getPackagesData?.complete_match.length, LANG_STRINGS.packageAccordingtoYourNeed)}
                    {getPackageContainer(getPackagesData?.complete_match, 'match')}
                    {!!getPackagesData?.partial_match.length && <hr className='hr-line' />}
                  </>
                )
              }
              {
                !!(getPackagesData?.partial_match.length > 0) && (
                  <>

                    {getTitle(getPackagesData.partial_match.length, LANG_STRINGS.insurancePackageWithSeveralofYourChoices)}
                    {getPackageContainer(getPackagesData.partial_match, 'partial_match')}
                    {!!getPackagesData?.no_match.length && <hr className='hr-line' />}
                  </>
                )
              }
              {
                !!(getPackagesData?.no_match.length > 0) && (
                  <>
                    {getTitle(getPackagesData.no_match.length, LANG_STRINGS.otherPackages)}
                    {getPackageContainer(getPackagesData.no_match, 'no_match')}
                  </>
                )
              }
            </>
          )
        }
        {
          (GET_PACKAGES_LOADER === false) && isPkgsEmpty && (
            <PackageNotFound history={history} productCode={pageData.productCode} />
          )
        }
        {
          addonsModal.showModal && (
            <AddonPackagesModal
              showModal={addonsModal.showModal}
              onCloseModal={handleCloseModal}
              onSubmitData={handleToGetPkgs}
              id='addon_add'
            />
          )
        }
        <ShowSnackbar />
      </PackageListStyle>
    </Container>
  )
}

export default connect(
  (state) => ({
    savedAddonsData: state.Policy.savedAddonsData
  }),
  {
    saveAddonsToStore
  }
)(PackageListOldContainer)
