import { Component } from 'react'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import { isEmpty } from 'lodash/lang'
import { get as lodashGet } from 'lodash/object'
import { AddonItemStyle } from './index.style'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText, Select } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import PolicyActions from '../../../../../redux/policy/action'
import QuantityAddRemove from '../../../../../components/QuantityAddRemove'
import AddonItemWithouLimit from '../AddonItemWithoutLimit'
import {
  DRIVER_PASS_DATA_CODE, ADDONS_THIRD_PARTY_AMOUNT_RANGE
} from '../../constants'

const { calculateAddonPremium } = PolicyActions

class AddonPackageItem extends Component {
  static propTypes = {
    item: PropTypes.object,
    selectedItem: PropTypes.object,
    onSelectItem: PropTypes.func
  }

  constructor (props) {
    super(props)
    const { selectedItem } = props

    this.state = this.getInitialState(selectedItem)
    this.initialPremium = (!isEmpty(selectedItem) && selectedItem.premium) || 0
    this.isQtyAddon = false
    this.defaultSelect = 0
  }

  getInitialState = (selectedItem) => {
    let initialState = {
      isChecked: false,
      selectedValue: '',
      premium: 0,
      qty: 1
    }
    if (!(isEmpty(selectedItem))) {
      initialState = {
        ...initialState,
        isChecked: true,
        selectedValue: this.getSelectedValue(selectedItem),
        qty: selectedItem.no_passanger,
        premium: selectedItem.premium
      }
    }
    return initialState
  }

  getSelectedValue = (item) => {
    return (item.premium && item.percentage) ? (item.premium / (item.percentage)) : 0
  }

  handleCalculatePremium = (addon) => {
    const { applicationData } = this.props
    this.props.calculateAddonPremium({
      code: 'car-protection',
      provider_package_map_code: applicationData.code,
      package_type: applicationData.package_type,
      addon_code: addon.add_on_code,
      addon_count: 1,
      sum_insured: addon.value,
      variant_code: applicationData.variant_code,
      year: applicationData.year,
      usage: applicationData.usage,
      vehicle_type: applicationData.vehicle_type
    })
  }

  handleOnChange = (e, defaultSelect) => {
    this.defaultSelect = defaultSelect
    this.setState(prevState => ({
      isChecked: !prevState.isChecked,
      selectedValue: defaultSelect,
      premium: !prevState.isChecked && 0
    }), () => {
      const { item } = this.props
      if (this.state.isChecked && item.calc_method === 'p_calc') {
        this.handleCalculatePremium({
          ...item,
          value: defaultSelect
        })
      }
      this.addTheItem(this.defaultSelect, 'chnage radio')
    })
  }

  addTheItem = (addonOnPremium = 0, type) => {
    const { item } = this.props
    const { isChecked, premium, qty } = this.state
    this.props.onSelectItem({
      ...item,
      addonOnPremium,
      premium: item.premium || premium || this.initialPremium,
      no_passanger: this.isQtyAddon ? qty : 0
    }, isChecked ? 'add' : '')
  }

  handleSelectChange = (value) => {
    const { item } = this.props
    if (item.calc_method === 'p_calc') {
      this.handleCalculatePremium({
        ...item,
        value
      })
    }
    this.setState({
      selectedValue: value,
      premium: this.getPremium(value)
    }, () => {
      this.addTheItem(parseInt(this.state.selectedValue, 10), 'select change')
    })
  }

  handleQty = (qty) => {
    this.setState({
      qty
    }, () => {
      this.addTheItem(parseInt(this.state.selectedValue, 10), 'qty')
    })
  }

  getPremium = (value) => {
    const { item = {} } = this.props
    this.initialPremium = value ? (value * item.percentage) : 0
    return this.initialPremium
  }

  render () {
    const { item = {}, selectedItem = {} } = this.props
    const { premium, show_drop_down: showPremiumDropDown } = item
    const data = ADDONS_THIRD_PARTY_AMOUNT_RANGE()
    let defaultSelect = showPremiumDropDown ? 15000000 : 0
    let addedPremium = selectedItem.premium || premium || this.state.premium
    if (DRIVER_PASS_DATA_CODE.includes(item.add_on_code)) {
      // data = ADDONS_PASSENGER_LIMIT
      defaultSelect = 25000000
    }
    this.isQtyAddon = item.add_on_code === 'passenger-insurance'
    if (!premium && addedPremium) {
      // there must be selected value for this case from select
      defaultSelect = selectedItem.addonOnPremium || defaultSelect
    } else if (!premium && showPremiumDropDown) {
      addedPremium = this.getPremium(defaultSelect)
    }
    if (this.state.qty) {
      addedPremium = addedPremium * this.state.qty
    }

    return (
      <AddonItemStyle>
        <AddonItemWithouLimit
          onChangeCheckBox={e => this.handleOnChange(e, defaultSelect)}
          name='firstCheckBox'
          title={item.add_on_name}
          premium={addedPremium}
          isChecked={this.state.isChecked}
          className='item-btm-border'
        />
        {
          showPremiumDropDown && (
            <Row align='center'>
              <CustomText
                size='12px'
                color={AgentColorPallette.fontSemiGrey}
              >
                {LANG_STRINGS.limit}
              </CustomText>
              <Select
                options={data}
                name='Limit'
                value={this.state.selectedValue || defaultSelect}
                defaultValue={defaultSelect}
                displayKey='display'
                placeholder='Limit'
                className='item-select-wrapper'
                disabled={!this.state.isChecked}
                onChange={this.handleSelectChange}
              />
              {
                this.isQtyAddon && (
                  <QuantityAddRemove
                    min={1}
                    max={7}
                    onUpdateQty={this.handleQty}
                    quantity={this.state.qty}
                  />
                )
              }
            </Row>
          )
        }
        {
          !!lodashGet(item, 'extra_details.length', 0) && (
            <ul className='addon-extra-detail'>
              {
                item.extra_details.map((extraDetail, index) => (
                  <li key={`extra_detail_${index}`}>{extraDetail}</li>
                ))
              }
            </ul>
          )
        }
      </AddonItemStyle>
    )
  }
}

export default connect(
  state => ({
    applicationData: state.Policy.applicationData
  }),
  {
    calculateAddonPremium
  }
)(AddonPackageItem)
