import { PACKAGES_ACTION } from './actions'
import { COMMON_ACTIONS } from '../../../../state/commonState/actions'

export const INITIAL_STATE = {

}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case PACKAGES_ACTION.GET_PACKAGES:
    case PACKAGES_ACTION.UPDATE_PACKAGE_STORE:
    case PACKAGES_ACTION.SEND_QUOTATION:
    case PACKAGES_ACTION.CREATE_APPLICATION:
    case COMMON_ACTIONS.UPDATE_DRAFT_QUOTATION:
    case PACKAGES_ACTION.SHARE_DRAFT_QUOTE:
      return {
        ...state,
        ...payload
      }
    case PACKAGES_ACTION.GET_PACKAGE_DETAIL:
      return {
        ...state,
        getPackageDetailData: payload?.getPackageDetailData?.code ? payload?.getPackageDetailData : state.getPackageDetailData
      }
    case PACKAGES_ACTION.SAVE_ADDONS_DATA:
      return {
        ...state,
        savedAddonsData: payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
