import { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { isEmpty } from 'lodash/lang'
import { get } from 'lodash/object'
import Cookies from 'universal-cookie'
import FullPageModal from '../../../../../components/FullPageModal'
import { APPLICATION_LANG } from '../../lang'
import AddonPackageItem from '../AddonPackageItem'
import { Button, Loader, CustomText } from '../../../../../components'
import policyActions from '../../../../../redux/policy/action'
import propertyActions from '../../../../../redux/property/actions'
import { BottomActionContainerStyle } from '../../../../../commonStyle/index.style'
import { INSURANCE_TYPE_COOKIES, PACKAGE_ADDONS_KEY } from '../../../../../constants/cookies'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { AddonsPackageModalStyle } from './index.style'
import { getPackagesReqBody } from '../../../../../helpers/getPackageBody'
import { removeFromLocalStorageData } from '../../../../../helpers/localstorage'

const { getAddonsList, saveAddonsToStore, resetPolicyStore } = policyActions
const { getPropertyAddons } = propertyActions
const cookies = new Cookies()

class AddonPackageModal extends Component {
  static propTypes = {
    showModal: PropTypes.bool,
    onCloseModal: PropTypes.func,
    onSubmitData: PropTypes.func
  }

  constructor (props) {
    super(props)
    this.state = {
      isBtnDisabled: isEmpty(props.savedAddonsData),
      preSelectedAddons: props.savedAddonsData
    }
    this.selectedItems = {
      ...props.savedAddonsData
    }
  }

  componentDidMount () {
    const { applicationData, policyData, productCode, isProviderAddons } = this.props
    if (isProviderAddons) {
      this.props.getPropertyAddons({
        pkgCode: applicationData.pkgCode,
        body: policyData || getPackagesReqBody(applicationData)
      })
      return
    }
    this.props.getAddonsList({
      apiId: productCode || cookies.get(INSURANCE_TYPE_COOKIES),
      policyData: policyData || getPackagesReqBody(applicationData)
    })
  }

  componentDidUpdate () {
    const { calcAddonPremium, calcAddonPremiumMsg } = this.props

    if (calcAddonPremiumMsg === 'success') {
      // if this then update the selectedItem and his state for premium
      const { add_on_code: addOnCode, premium } = calcAddonPremium
      this.updatePreSelectedState(addOnCode, premium)
      this.props.resetPolicyStore(['calcAddonPremiumMsg'])
    }
  }

  updatePreSelectedState = (addOnCode, premium) => {
    this.setState(prevState => ({
      preSelectedAddons: {
        ...prevState.preSelectedAddons,
        [addOnCode]: {
          ...this.selectedItems[addOnCode],
          premium
        }
      }
    }))
  }

  handleSelectedItem = (item, actionType) => {
    if (actionType === 'add') {
      // only add if action type is add
      this.selectedItems = {
        ...this.selectedItems,
        [item.add_on_code]: item
      }
      this.updatePreSelectedState(item.add_on_code, item.premium)
      if (this.state.isBtnDisabled) {
        this.setState({
          isBtnDisabled: false
        })
      }
    } else {
      // remove the item if it not added action
      delete this.selectedItems[item.add_on_code]
      if (item.add_on_code === 'driver-insurance') {
        delete this.selectedItems['passenger-insurance']
      }
      this.setState(prevState => {
        const { preSelectedAddons } = prevState
        delete preSelectedAddons[item.add_on_code]
        if (item.add_on_code === 'driver-insurance') {
          delete preSelectedAddons['passenger-insurance']
        }
        return {
          preSelectedAddons
        }
      })
    }

    if (isEmpty(this.selectedItems)) {
      if (!isEmpty(this.props.savedAddonsData)) {
        // if user remove all selectedAddons then also
        // clear the localstorage and store
        this.props.saveAddonsToStore({})
        removeFromLocalStorageData(PACKAGE_ADDONS_KEY)
      }
      this.setState({
        isBtnDisabled: true
      })
    }
  }

  handleSubmit = () => {
    if (isEmpty(this.selectedItems)) {
      // exit if user not selected
      return
    }
    // this is add the data and call api to get packages for the details
    const { preSelectedAddons } = this.state
    const body = {
      ...this.selectedItems,
      ...preSelectedAddons
    }
    this.props.onSubmitData(body)
  }

  getAddonItem = (item, preSelectedAddons) => {
    const itemCode = item.add_on_code
    const isDriverInsuredSelected = get(preSelectedAddons, '[driver-insurance].add_on_code', '') === 'driver-insurance'
    if (itemCode !== 'passenger-insurance') {
      return (
        <AddonPackageItem
          item={item}
          key={itemCode}
          selectedItem={preSelectedAddons[itemCode]}
          onSelectItem={this.handleSelectedItem}
        />
      )
    } else if (isDriverInsuredSelected && itemCode === 'passenger-insurance') {
      return (
        <AddonPackageItem
          item={item}
          key={itemCode}
          selectedItem={preSelectedAddons[itemCode]}
          onSelectItem={this.handleSelectedItem}
        />
      )
    }
    return null
  }

  render () {
    const {
      showModal, onCloseModal, isLoading, providerAddonsLoader,
      calcAddonPreLoader, addonsData = [], providerAddonsData = []
    } = this.props
    const { preSelectedAddons } = this.state
    const addonsDataMap = providerAddonsData.length ? providerAddonsData : addonsData
    return (
      <FullPageModal
        onCloseModal={onCloseModal}
        showModal={showModal}
        header={APPLICATION_LANG.addProtection}
      >
        <Loader visible={isLoading || calcAddonPreLoader || providerAddonsLoader} bgColor={AgentColorPallette.fontLightGrey}>
          {
            !!addonsDataMap.length && addonsDataMap.map((item, index) => (
              <AddonsPackageModalStyle key={item.category_code} bottom={(index + 1) !== addonsData.length}>
                <CustomText
                  size='16px'
                  weight={800}
                  color={AgentColorPallette.black}
                  className='addons-category'
                >
                  {item.category_name}
                </CustomText>
                {
                  item.add_on.map(item => (this.getAddonItem(item, preSelectedAddons)))
                }
              </AddonsPackageModalStyle>
            ))
          }
          <BottomActionContainerStyle>
            <Button onClick={this.handleSubmit} disabled={this.state.isBtnDisabled}>
              {APPLICATION_LANG.addProtection}
            </Button>
          </BottomActionContainerStyle>
        </Loader>
      </FullPageModal>
    )
  }
}

export default connect(
  state => ({
    addonsData: state.Policy.addonsData,
    applicationData: state.Policy.applicationData,
    savedAddonsData: state.Policy.savedAddonsData,
    calcAddonPremium: state.Policy.calcAddonPremium,
    calcAddonPremiumMsg: state.Policy.calcAddonPremiumMsg,
    calcAddonPreError: state.Error.CALCULATE_ADDON_PREMIUM,
    calcAddonPreLoader: state.Loading.CALCULATE_ADDON_PREMIUM,
    providerAddonsStatus: state.Property.propertyAddonsStatus,
    providerAddonsData: state.Property.propertyAddonsData,
    isLoading: state.Loading.GET_ADDONS_LIST,
    providerAddonsLoader: state.Loading.GET_PROPERTY_ADDONS,
    addonsError: state.Error.GET_ADDONS_LIST
  }),
  {
    saveAddonsToStore,
    getPropertyAddons,
    resetPolicyStore,
    getAddonsList
  }
)(AddonPackageModal)
